def main():
    ap=argparse.ArgumentParser();ap.add_argument('--output',type=Path,default=BASE);a=ap.parse_args();out=a.output.resolve()
    for n,d in DESIGNS.items():
        ad=out/f'audits/{n}';f=load(ad/'frozen_ledger.json');choice=next(o for o in f['candidate_comparison'] if [o['country'],o['key']]==d['choice']);assert choice['eligible']
        hh=sorted([e for e in f['verified_events'] if e['id'] in choice['event_ids']],key=lambda e:(dt(e['date']),e['start'] or 0,e['id']))
        stages=[];blocks=[{'id':'A01','type':'inference','text':d['overall'],'premise_event_ids':[e['id'] for e in hh]}]
        for i,(start,end,basis) in enumerate(d['ranges']):
            ee=[e for e in hh if dt(start)<=dt(e['date'])<=dt(end)];assert ee
            stages.append({'dates':sorted({e['date'] for e in ee},key=dt),'events':[e['id'] for e in ee],'boundary_basis':basis,'range_labels':[start,end]})
            blocks.append({'id':f'S{i+1}','type':'inference','text':d['stages'][i],'premise_event_ids':[e['id'] for e in ee]})
        assert {e for s in stages for e in s['events']}==set(choice['event_ids'])
        units='架次' if choice['kind']=='飞机' else '艘次';tasks=Counter(e['facts']['task'] for e in hh);quantity=sum(e['facts']['quantity'] for e in hh)
        text=f"统计口径：本主线在5月1日至{dt(n).month}月{dt(n).day}日的{(dt(n)-dt('2025.5.1')).days+1}个日历日输入视图内，核实{len(choice['dates'])}个证据日期、{len(hh)}起活动，参加数量合计{quantity}{units}。按活动计的任务分布为"+'、'.join(f'{k}{v}起' for k,v in tasks.items())+'。无可信记录的日期包含缺证或冲突排除，不作零活动；活动数、参加数量与去重实体数不互换。'
        blocks.append({'id':'Q01','type':'provided_fact','text':text,'premise_event_ids':[e['id'] for e in hh]})
        if 'external' in d:blocks.append({'id':'E01','type':'external_background','text':d['external'],'premise_event_ids':choice['today_ids']})
        blocks.append({'id':'A02','type':'inference','text':d['alternative'],'premise_event_ids':[e['id'] for e in hh]})
        selection={**choice,'events':choice['event_ids'],'stages':stages,'selection_reason':d['selection'],'identity_scope':'具名舰艇的专名活动记录；不证明间隔连续部署' if choice['identity_scope']=='named_vessel' else '同主体同型号/舰级；不证明同一物理实体'}
        comparisons=[]
        for c,k,reason in d['alternatives']:
            q=next((o for o in f['candidate_comparison'] if o['country']==c and o['key']==k),None)
            comparisons.append({'country':c,'key':k,'qualified':q is not None and q['eligible'],'event_ids':q['event_ids'] if q else [],'specific_reason':reason,'absent_reason':'当日本轮可信种子中不存在；相关冲突候选可调查，不编造合格主线' if q is None else None})
        snap={'schema_version':13,'frozen_sha256':sha(ad/'frozen_ledger.json'),'question':d['question'],'selection':selection,'blocks':blocks,'next_focus':d['next'],'authoring':'当前Codex代理逐节点阅读本轮事实后直接撰写；无额外模型API；复现时按哈希回放','semantic_review_status':'authored_pending_final_document_review','comparison':comparisons,'all_qualified_screen':f['candidate_comparison'],'previous_text_reuse':'未加载旧分析快照或保留旧段落；相同事实结论重新论证'}
        save(ad/'analysis_snapshot.json',snap);save(ad/'mainline_selection.json',{'frozen_sha256':snap['frozen_sha256'],'selected':selection,'representative_comparisons':comparisons,'all_screened':f['candidate_comparison']})
        (ad/'analysis.md').write_text('## 二、重点态势分析\n\n'+d['question']+'\n\n'+'\n\n'.join(b['text'] for b in blocks),encoding='utf8')
        print(n,choice['country'],choice['key'],len(hh),len(choice['dates']),quantity,flush=True)
if __name__=='__main__':main()
